package org.jfree.chart.block;

import java.awt.Graphics2D;
import java.awt.geom.Rectangle2D;
import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.jfree.chart.block.Block;
import org.jfree.chart.block.BlockContainer;
import org.jfree.chart.block.BorderArrangement;
import org.jfree.chart.block.RectangleConstraint;
import org.jfree.chart.util.ObjectUtilities;
import org.jfree.chart.util.RectangleEdge;
import org.jfree.chart.util.Size2D;
import org.jfree.data.Range;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Unit tests for BorderArrangement.arrangeFF.
 * Since arrangeFF is protected, we use a subclass or reflection. 
 * Here we use a testable subclass.
 */
public class BorderArrangement_arrangeFF_TriageGen2Test {

    private TestableBorderArrangement arrangement;
    private BlockContainer container;
    private Graphics2D g2;
    private RectangleConstraint constraint;

    // Subclass to access protected method and expose internal blocks for testing
    private static class TestableBorderArrangement extends BorderArrangement {
        public Block topBlock;
        public Block bottomBlock;
        public Block leftBlock;
        public Block rightBlock;
        public Block centerBlock;

        // We need to simulate the field setting because the original class uses internal fields
        // In JFreeChart, these are usually set via the add(Block, Object) method.
        // However, to control exactly which block is which for the arrangeFF logic, 
        // we simulate the internal state.

        @Override
        public void add(Block block, Object key) {
            super.add(block, key);
            // Mapping keys to fields to match the logic in arrangeFF
            if ("Top".equals(key)) this.topBlock = block;
            else if ("Bottom".equals(key)) this.bottomBlock = block;
            else if ("Left".equals(key)) this.leftBlock = block;
            else if ("Right".equals(key)) this.rightBlock = block;
            else if ("Center".equals(key)) this.centerBlock = block;
        }

        // Using reflection or providing a way to inject mocks into the protected fields
        // Since we cannot change the source, we use the 'add' method which is public.
        // Note: The actual arrangeFF uses 'this.topBlock' etc. 
        // In the real BorderArrangement, these are fields.

        // We must use Reflection to set the private/protected fields if 'add' doesn't map them 1:1
        // But based on the provided code, arrangeFF accesses this.topBlock, etc.
        // Let's assume the 'add' method is the standard way.

        public Size2D callArrangeFF(BlockContainer c, Graphics2D g, RectangleConstraint r) {
            return super.arrangeFF(c, g, r);
        }

        // For the sake of this test, we will use reflection to inject the mocks 
        // because the provided snippet shows 'this.topBlock' being accessed directly.
        public void setField(String fieldName, Block block) throws Exception {
            java.lang.reflect.Field field = BorderArrangement.class.getDeclaredField(fieldName);
            field.setAccessible(true);
            field.set(this, block);
        }
    }

    @Before
    public void setUp() {
        arrangement = new TestableBorderArrangement();
        container = mock(BlockContainer.class);
        g2 = mock(Graphics2D.class);
        constraint = new RectangleConstraint(100.0, 200.0);
    }

    @Test
    public void testArrangeFF_AllBlocksPresent() throws Exception {
        Block top = mock(Block.class);
        Block bottom = mock(Block.class);
        Block left = mock(Block.class);
        Block right = mock(Block.class);
        Block center = mock(Block.class);

        arrangement.setField("topBlock", top);
        arrangement.setField("bottomBlock", bottom);
        arrangement.setField("leftBlock", left);
        arrangement.setField("rightBlock", right);
        arrangement.setField("centerBlock", center);

        when(top.arrange(any(), any())).thenReturn(new Size2D(100.0, 50.0));
        when(bottom.arrange(any(), any())).thenReturn(new Size2D(100.0, 50.0));
        when(left.arrange(any(), any())).thenReturn(new Size2D(20.0, 100.0));
        when(right.arrange(any(), any())).thenReturn(new Size2D(20.0, 100.0));

        Size2D result = arrangement.callArrangeFF(container, g2, constraint);

        assertEquals(100.0, result.getWidth(), 0.001);
        assertEquals(200.0, result.getHeight(), 0.001);

        // Verify bounds for Top: (0, 0, 100, 50)
        verify(top).setBounds(new Rectangle2D.Double(0.0, 0.0, 100.0, 50.0));
        // Verify bounds for Bottom: h[0]=50, h[2]=200-50-50=100. Bottom Y = 50 + 100 = 150.
        verify(bottom).setBounds(new Rectangle2D.Double(0.0, 150.0, 100.0, 50.0));
        // Verify bounds for Left: h[0]=50, h[2]=100. Left Y = 50.
        verify(left).setBounds(new Rectangle2D.Double(0.0, 50.0, 20.0, 100.0));
        // Verify bounds for Right: w[2]=20, w[4]=100-20-20=60. Right X = 20 + 60 = 80.
        verify(right).setBounds(new Rectangle2D.Double(80.0, 50.0, 20.0, 100.0));
        // Verify bounds for Center: w[2]=20, h[0]=50, w[4]=60, h[4]=100.
        verify(center).setBounds(new Rectangle2D.Double(20.0, 50.0, 60.0, 100.0));
    }

    @Test
    public void testArrangeFF_NoBlocks() throws Exception {
        arrangement.setField("topBlock", null);
        arrangement.setField("bottomBlock", null);
        arrangement.setField("leftBlock", null);
        arrangement.setField("rightBlock", null);
        arrangement.setField("centerBlock", null);

        Size2D result = arrangement.callArrangeFF(container, g2, constraint);

        assertEquals(100.0, result.getWidth(), 0.001);
        assertEquals(200.0, result.getHeight(), 0.001);
    }

    @Test
    public void testArrangeFF_OnlyTopAndCenter() throws Exception {
        Block top = mock(Block.class);
        Block center = mock(Block.class);

        arrangement.setField("topBlock", top);
        arrangement.setField("centerBlock", center);

        when(top.arrange(any(), any())).thenReturn(new Size2D(100.0, 40.0));

        arrangement.callArrangeFF(container, g2, constraint);

        verify(top).setBounds(new Rectangle2D.Double(0.0, 0.0, 100.0, 40.0));
        verify(center).setBounds(new Rectangle2D.Double(0.0, 40.0, 100.0, 160.0));
    }

    @Test
    public void testArrangeFF_OnlyBottomAndLeft() throws Exception {
        Block bottom = mock(Block.class);
        Block left = mock(Block.class);

        arrangement.setField("bottomBlock", bottom);
        arrangement.setField("leftBlock", left);

        // h[0] = 0
        // h[1] (bottom height) = 30
        // h[2] = 200 - 30 - 0 = 170
        when(bottom.arrange(any(), any())).thenReturn(new Size2D(100.0, 30.0));
        when(left.arrange(any(), any())).thenReturn(new Size2D(10.0, 170.0));

        arrangement.callArrangeFF(container, g2, constraint);

        // Bottom: Y = h[0] + h[2] = 0 + 170 = 170
        verify(bottom).setBounds(new Rectangle2D.Double(0.0, 170.0, 100.0, 30.0));
        // Left: Y = h[0] = 0
        verify(left).setBounds(new Rectangle2D.Double(0.0, 0.0, 10.0, 170.0));
    }

    @Test
    public void testArrangeFF_OnlyRight() throws Exception {
        Block right = mock(Block.class);
        arrangement.setField("rightBlock", right);

        // h[0]=0, h[1]=0, h[2]=200
        // w[2]=0, w[3]=30, w[4]=100-30-0=70
        when(right.arrange(any(), any())).thenReturn(new Size2D(30.0, 200.0));

        arrangement.callArrangeFF(container, g2, constraint);

        // Right: X = w[2] + w[4] = 0 + 70 = 70
        verify(right).setBounds(new Rectangle2D.Double(70.0, 0.0, 30.0, 200.0));
    }
}
